5489: # Whether a variable name is a host marker (Windows: case-insensitive, like its environment).
5490: function Test-HostMarkerName {
5491:     param([string]$Name)
5492:     $n = $Name
5493:     if ($script:OnWindows) { $n = $n.ToUpperInvariant() }
5494:     if ($script:HostMarkerNames -ccontains $n) { return $true }
5495:     foreach ($p in $script:HostMarkerPrefixes) { if ($n.StartsWith($p, [StringComparison]::Ordinal)) { return $true } }
