5499: # The host markers set in THIS process's environment, sorted ordinal: string[] (maybe empty).
5500: function Get-HostMarkerNames {
5501:     $names = New-Object System.Collections.Generic.List[string]
5502:     foreach ($k in @([Environment]::GetEnvironmentVariables().Keys)) {
5503:         $n = [string]$k
5504:         if ((Test-HostMarkerName $n) -and -not $names.Contains($n)) { $names.Add($n) }
5505:     }
5506:     $arr = [string[]]$names.ToArray()
5507:     [Array]::Sort($arr, [StringComparer]::Ordinal)
5508:     return , $arr
5509: }
