5511: # Removes the host markers from THIS process's environment right before an engine child is started
5512: # (Start-Process has no environment parameter on Windows PowerShell 5.1: the child inherits the
5513: # process's block) and returns what was removed (name -> value) for Restore-HostMarkers, which the
5514: # caller runs in a `finally` right after the start - the bridge's own process keeps its markers.
5515: function Hide-HostMarkers {
5516:     $saved = [ordered]@{}
5517:     foreach ($n in (Get-HostMarkerNames)) {
5518:         $saved[$n] = [Environment]::GetEnvironmentVariable($n)
5519:         # a real null: PowerShell passes $null to a [string] argument as '' - which PowerShell 7
5520:         # (.NET) keeps as an EMPTY variable instead of removing it
5521:         [Environment]::SetEnvironmentVariable($n, [NullString]::Value)
5522:     }
5523:     return $saved
5524: }
5525: 
5526: function Restore-HostMarkers {
5527:     param($Saved)
5528:     if ($null -eq $Saved) { return }
5529:     foreach ($n in @($Saved.Keys)) { [Environment]::SetEnvironmentVariable([string]$n, [string]$Saved[$n]) }
5530: }
