5541: # (D3, F03-3, F04-5) The coordinator's host - a HINT inferred from its markers, never an identity:
5542: # `codex` (CODEX_SESSION_ID or CODEX_THREAD_ID - looked at FIRST: a codex session started from a
5543: # claude-code session inherits that session's markers, and its own are the innermost), (wave 27b)
5544: # `zcode` (ZCODE_SESSION_ID or ZCODE_PROJECT_DIR - looked at before claude-code: Z Code sets no
5545: # claude-code marker of its own, so a claude-code marker next to its own is taken as inherited), `claude-code`
5546: # (CLAUDECODE, CLAUDE_CODE_ENTRYPOINT, or AI_AGENT starting with claude-code), else `unknown`.
5547: function Get-CoordinatorHost {
5548:     $get = { param($n) [string][Environment]::GetEnvironmentVariable($n) }
5549:     if ((& $get 'CODEX_SESSION_ID') -or (& $get 'CODEX_THREAD_ID')) { return 'codex' }
5550:     if ((& $get 'ZCODE_SESSION_ID') -or (& $get 'ZCODE_PROJECT_DIR')) { return 'zcode' }
5551:     if ((& $get 'CLAUDECODE') -or (& $get 'CLAUDE_CODE_ENTRYPOINT') -or (& $get 'AI_AGENT').StartsWith('claude-code', [StringComparison]::OrdinalIgnoreCase)) { return 'claude-code' }
5552:     return 'unknown'
5553: }
